unsafe fn putd(o:*mut u8,p:usize,x:f64){for(k,b)in x.to_le_bytes().iter().enumerate(){*o.add(p+k)=*b}}
#[no_mangle]
pub unsafe extern "C" fn ordinary_least_squares_regressor(v:*const i64,n:usize,out:*mut u8,cap:usize)->i64{if v.is_null()||n<6{return -1}let a=std::slice::from_raw_parts(v,n);let nr=a[0];let f=a[1];let t=a[2];if !(2..=8).contains(&nr)||f!=2||!(1..=3).contains(&t)||n!=3+nr as usize*3+t as usize*2{return -1}let mut g=[[0.0;3];3];let mut b=[0.0;3];let mut p=3;for _ in 0..nr{let x=a[p];let y=a[p+1];let zt=a[p+2];p+=3;if !(-100..=100).contains(&x)||!(-100..=100).contains(&y)||!(-1000..=1000).contains(&zt){return -1}let z=[x as f64,y as f64,1.0];for i in 0..3{b[i]+=z[i]*zt as f64;for j in 0..3{g[i][j]+=z[i]*z[j]}}}for c in 0..3{let mut q=c;for r in c+1..3{if g[r][c].abs()>g[q][c].abs(){q=r}}if g[q][c].abs()<1e-12{return -1}g.swap(c,q);b.swap(c,q);let s=g[c][c];for j in c..3{g[c][j]/=s}b[c]/=s;for r in 0..3{if r!=c{let k=g[r][c];for j in c..3{g[r][j]-=k*g[c][j]}b[r]-=k*b[c]}}}if out.is_null()||cap<t as usize*8{return -2}for r in 0..t as usize{let x=a[p];let y=a[p+1];p+=2;if !(-100..=100).contains(&x)||!(-100..=100).contains(&y){return -1}putd(out,r*8,x as f64*b[0]+y as f64*b[1]+b[2])}t*8}
